71		public EntryConfig(short mcc, short mnc, char[] language,
72				char[] region, byte orientation,
73				byte touchscreen, int density, byte keyboard, byte navigation,
74				byte inputFlags, byte grammaticalInflection, short screenWidth, short screenHeight,
75				short sdkVersion, byte screenLayout, byte uiMode,
76				short smallestScreenWidthDp, short screenWidthDp,
77				short screenHeightDp, char[] localeScript, char[] localeVariant,
78				byte screenLayout2, byte colorMode, boolean isInvalid, int size) {
79			if (orientation < 0 || orientation > 3) {
80				LOG.warn("Invalid orientation value: {}", orientation);
81				orientation = 0;
82				isInvalid = true;
83			}
84			if (touchscreen < 0 || touchscreen > 3) {
85				LOG.warn("Invalid touchscreen value: {}", touchscreen);
86				touchscreen = 0;
87				isInvalid = true;
88			}
89			if (density < -1) {
90				LOG.warn("Invalid density value: {}", density);
91				density = 0;
92				isInvalid = true;
93			}
94			if (keyboard < 0 || keyboard > 3) {
95				LOG.warn("Invalid keyboard value: {}", keyboard);
96				keyboard = 0;
97				isInvalid = true;
98			}
99			if (navigation < 0 || navigation > 4) {
100				LOG.warn("Invalid navigation value: {}", navigation);
101				navigation = 0;
102				isInvalid = true;
103			}
104	
105			if (localeScript != null && localeScript.length != 0) {
106				if (localeScript[0] == '\00') {
107					localeScript = null;
108				}
109			} else {
110				localeScript = null;
111			}
112	
113			if (localeVariant != null && localeVariant.length != 0) {
114				if (localeVariant[0] == '\00') {
115					localeVariant = null;
116				}
117			} else {
118				localeVariant = null;
119			}
120	
121			this.mcc = mcc;
122			this.mnc = mnc;
123			this.language = language;
124			this.region = region;
125			this.orientation = orientation;
126			this.touchscreen = touchscreen;
127			this.density = density;
128			this.keyboard = keyboard;
129			this.navigation = navigation;
130			this.inputFlags = inputFlags;
131			this.grammaticalInflection = grammaticalInflection;
132			this.screenWidth = screenWidth;
133			this.screenHeight = screenHeight;
134			this.sdkVersion = sdkVersion;
135			this.screenLayout = screenLayout;
136			this.uiMode = uiMode;
137			this.smallestScreenWidthDp = smallestScreenWidthDp;
138			this.screenWidthDp = screenWidthDp;
139			this.screenHeightDp = screenHeightDp;
140			this.localeScript = localeScript;
141			this.localeVariant = localeVariant;
142			this.screenLayout2 = screenLayout2;
143			this.colorMode = colorMode;
144			this.isInvalid = isInvalid;
145			this.size = size;
146			mQualifiers = generateQualifiers();
147		}
