153		private String generateQualifiers() {
154			StringBuilder ret = new StringBuilder();
155			if (mcc != 0) {
156				ret.append("-mcc").append(String.format("%03d", mcc));
157				if (mnc != MNC_ZERO) {
158					if (mnc != 0) {
159						ret.append("-mnc");
160						if (size <= 32) {
161							if (mnc > 0 && mnc < 10) {
162								ret.append(String.format("%02d", mnc));
163							} else {
164								ret.append(String.format("%03d", mnc));
165							}
166						} else {
167							ret.append(mnc);
168						}
169					}
170				} else {
171					ret.append("-mnc00");
172				}
173			} else {
174				if (mnc != 0) {
175					ret.append("-mnc").append(mnc);
176				}
177			}
178			ret.append(getLocaleString());
179	
180			switch (grammaticalInflection) {
181				case GRAMMATICAL_GENDER_NEUTER:
182					ret.append("-neuter");
183					break;
184				case GRAMMATICAL_GENDER_FEMININE:
185					ret.append("-feminine");
186					break;
187				case GRAMMATICAL_GENDER_MASCULINE:
188					ret.append("-masculine");
189					break;
190			}
191	
192			switch (screenLayout & MASK_LAYOUTDIR) {
193				case SCREENLAYOUT_LAYOUTDIR_RTL:
194					ret.append("-ldrtl");
195					break;
196				case SCREENLAYOUT_LAYOUTDIR_LTR:
197					ret.append("-ldltr");
198					break;
199			}
200			if (smallestScreenWidthDp != 0) {
201				ret.append("-sw").append(smallestScreenWidthDp).append("dp");
202			}
203			if (screenWidthDp != 0) {
204				ret.append("-w").append(screenWidthDp).append("dp");
205			}
206			if (screenHeightDp != 0) {
207				ret.append("-h").append(screenHeightDp).append("dp");
208			}
209			switch (screenLayout & MASK_SCREENSIZE) {
210				case SCREENSIZE_SMALL:
211					ret.append("-small");
212					break;
213				case SCREENSIZE_NORMAL:
214					ret.append("-normal");
215					break;
216				case SCREENSIZE_LARGE:
217					ret.append("-large");
218					break;
219				case SCREENSIZE_XLARGE:
220					ret.append("-xlarge");
221					break;
222			}
223			switch (screenLayout & MASK_SCREENLONG) {
224				case SCREENLONG_YES:
225					ret.append("-long");
226					break;
227				case SCREENLONG_NO:
228					ret.append("-notlong");
229					break;
230			}
231			switch (screenLayout2 & MASK_SCREENROUND) {
232				case SCREENLAYOUT_ROUND_NO:
233					ret.append("-notround");
234					break;
235				case SCREENLAYOUT_ROUND_YES:
236					ret.append("-round");
237					break;
238			}
239			switch (colorMode & COLOR_HDR_MASK) {
240				case COLOR_HDR_YES:
241					ret.append("-highdr");
242					break;
243				case COLOR_HDR_NO:
244					ret.append("-lowdr");
245					break;
246			}
247			switch (colorMode & COLOR_WIDE_MASK) {
248				case COLOR_WIDE_YES:
249					ret.append("-widecg");
250					break;
251				case COLOR_WIDE_NO:
252					ret.append("-nowidecg");
253					break;
254			}
255			switch (orientation) {
256				case ORIENTATION_PORT:
257					ret.append("-port");
258					break;
259				case ORIENTATION_LAND:
260					ret.append("-land");
261					break;
262				case ORIENTATION_SQUARE:
263					ret.append("-square");
264					break;
265			}
266			switch (uiMode & MASK_UI_MODE_TYPE) {
267				case UI_MODE_TYPE_CAR:
268					ret.append("-car");
269					break;
270				case UI_MODE_TYPE_DESK:
271					ret.append("-desk");
272					break;
273				case UI_MODE_TYPE_TELEVISION:
274					ret.append("-television");
275					break;
276				case UI_MODE_TYPE_SMALLUI:
277					ret.append("-smallui");
278					break;
279				case UI_MODE_TYPE_MEDIUMUI:
280					ret.append("-mediumui");
281					break;
282				case UI_MODE_TYPE_LARGEUI:
283					ret.append("-largeui");
284					break;
285				case UI_MODE_TYPE_GODZILLAUI:
286					ret.append("-godzillaui");
287					break;
288				case UI_MODE_TYPE_HUGEUI:
289					ret.append("-hugeui");
290					break;
291				case UI_MODE_TYPE_APPLIANCE:
292					ret.append("-appliance");
293					break;
294				case UI_MODE_TYPE_WATCH:
295					ret.append("-watch");
296					break;
297				case UI_MODE_TYPE_VR_HEADSET:
298					ret.append("-vrheadset");
299					break;
300			}
301			switch (uiMode & MASK_UI_MODE_NIGHT) {
302				case UI_MODE_NIGHT_YES:
303					ret.append("-night");
304					break;
305				case UI_MODE_NIGHT_NO:
306					ret.append("-notnight");
307					break;
308			}
309			switch (density) {
310				case DENSITY_DEFAULT:
311					break;
312				case DENSITY_LOW:
313					ret.append("-ldpi");
314					break;
315				case DENSITY_MEDIUM:
316					ret.append("-mdpi");
317					break;
318				case DENSITY_HIGH:
319					ret.append("-hdpi");
320					break;
321				case DENSITY_TV:
322					ret.append("-tvdpi");
323					break;
324				case DENSITY_XHIGH:
325					ret.append("-xhdpi");
326					break;
327				case DENSITY_XXHIGH:
328					ret.append("-xxhdpi");
329					break;
330				case DENSITY_XXXHIGH:
331					ret.append("-xxxhdpi");
332					break;
333				case DENSITY_ANY:
334					ret.append("-anydpi");
335					break;
336				case DENSITY_NONE:
337					ret.append("-nodpi");
338					break;
339				default:
340					ret.append('-').append(density).append("dpi");
341			}
342			switch (touchscreen) {
343				case TOUCHSCREEN_NOTOUCH:
344					ret.append("-notouch");
345					break;
346				case TOUCHSCREEN_STYLUS:
347					ret.append("-stylus");
348					break;
349				case TOUCHSCREEN_FINGER:
350					ret.append("-finger");
351					break;
352			}
353			switch (inputFlags & MASK_KEYSHIDDEN) {
354				case KEYSHIDDEN_NO:
355					ret.append("-keysexposed");
356					break;
357				case KEYSHIDDEN_YES:
358					ret.append("-keyshidden");
359					break;
360				case KEYSHIDDEN_SOFT:
361					ret.append("-keyssoft");
362					break;
363			}
364			switch (keyboard) {
365				case KEYBOARD_NOKEYS:
366					ret.append("-nokeys");
367					break;
368				case KEYBOARD_QWERTY:
369					ret.append("-qwerty");
370					break;
371				case KEYBOARD_12KEY:
372					ret.append("-12key");
373					break;
374			}
375			switch (inputFlags & MASK_NAVHIDDEN) {
376				case NAVHIDDEN_NO:
377					ret.append("-navexposed");
378					break;
379				case NAVHIDDEN_YES:
380					ret.append("-navhidden");
381					break;
382			}
383			switch (navigation) {
384				case NAVIGATION_NONAV:
385					ret.append("-nonav");
386					break;
387				case NAVIGATION_DPAD:
388					ret.append("-dpad");
389					break;
390				case NAVIGATION_TRACKBALL:
391					ret.append("-trackball");
392					break;
393				case NAVIGATION_WHEEL:
394					ret.append("-wheel");
395					break;
396			}
397			if (screenWidth != 0 && screenHeight != 0) {
398				if (screenWidth > screenHeight) {
399					ret.append(String.format("-%dx%d", screenWidth, screenHeight));
400				} else {
401					ret.append(String.format("-%dx%d", screenHeight, screenWidth));
402				}
403			}
404			if (sdkVersion > 0 && sdkVersion >= getNaturalSdkVersionRequirement()) {
405				ret.append("-v").append(sdkVersion);
406			}
407			if (isInvalid) {
408				ret.append("-ERR").append(sErrCounter++);
409			}
410	
411			return ret.toString();
412		}
413	
414		private short getNaturalSdkVersionRequirement() {
415			if ((uiMode & MASK_UI_MODE_TYPE) == UI_MODE_TYPE_VR_HEADSET || (colorMode & COLOR_WIDE_MASK) != 0
416					|| ((colorMode & COLOR_HDR_MASK) != 0)) {
417				return SDK_OREO;
418			}
419			if ((screenLayout2 & MASK_SCREENROUND) != 0) {
420				return SDK_MNC;
421			}
422			if (density == DENSITY_ANY) {
423				return SDK_LOLLIPOP;
424			}
425			if (smallestScreenWidthDp != 0 || screenWidthDp != 0 || screenHeightDp != 0) {
426				return SDK_HONEYCOMB_MR2;
427			}
428			if ((uiMode & (MASK_UI_MODE_TYPE | MASK_UI_MODE_NIGHT)) != UI_MODE_NIGHT_ANY) {
429				return SDK_FROYO;
430			}
431			if ((screenLayout & (MASK_SCREENSIZE | MASK_SCREENLONG)) != SCREENSIZE_ANY || density != DENSITY_DEFAULT) {
432				return SDK_DONUT;
433			}
434			return 0;
435		}
