437		private String getLocaleString() {
438			StringBuilder sb = new StringBuilder();
439	
440			// check for old style non BCP47 tags
441			// allows values-xx-rXX, values-xx, values-xxx-rXX
442			// denies values-xxx, anything else
443			if (localeVariant == null && localeScript == null && (region[0] != '\00' || language[0] != '\00')
444					&& region.length != 3) {
445				sb.append('-').append(language);
446				if (region[0] != '\00') {
447					sb.append("-r").append(region);
448				}
449			} else { // BCP47
450				if (language[0] == '\00' && region[0] == '\00') {
451					return sb.toString(); // early return, no language or region
452				}
453				sb.append("-b+");
454				if (language[0] != '\00') {
455					sb.append(language);
456				}
457				if (localeScript != null && localeScript.length == 4) {
458					sb.append('+').append(localeScript);
459				}
460				if ((region.length == 2 || region.length == 3) && region[0] != '\00') {
461					sb.append('+').append(region);
462				}
463				if (localeVariant != null && localeVariant.length >= 5) {
464					sb.append('+').append(toUpper(localeVariant));
465				}
466			}
467			return sb.toString();
468		}
469	
470		private String toUpper(char[] character) {
471			StringBuilder sb = new StringBuilder();
472			for (char ch : character) {
473				sb.append(Character.toUpperCase(ch));
474			}
475			return sb.toString();
476		}
